import React, { useState } from "react";

function LoginPage() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      // 1. Отримуємо токени
      const res = await fetch("http://127.0.0.1:8000/api/token/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username, password }),
      });

      const data = await res.json();

      if (!data.access) {
        alert("Невірний логін або пароль");
        return;
      }

      localStorage.setItem("token", data.access);
      localStorage.setItem("refresh", data.refresh);

      // 2. Отримуємо дані користувача
      const userRes = await fetch("http://127.0.0.1:8000/api/user/", {
        headers: { Authorization: `Bearer ${data.access}` },
      });
      if (!userRes.ok) throw new Error("Не вдалося отримати дані користувача");

      const userData = await userRes.json();

      // 3. Зберігаємо в localStorage прапорці адміністратора
      localStorage.setItem("is_staff", userData.is_staff);
      localStorage.setItem("is_superuser", userData.is_superuser);

      // 4. Перенаправляємо на головну
      window.location.href = "/";
    } catch (error) {
      console.error("Помилка входу:", error);
      alert("Помилка входу, перевірте консоль");
    }
  };

  return (
    <div className="login-container">
      <h2>Вхід</h2>
      <form onSubmit={handleLogin}>
        <input
          type="text"
          placeholder="Логін"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          required
        />
        <input
          type="password"
          placeholder="Пароль"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
        />
        <button type="submit">Увійти</button>
      </form>
    </div>
  );
}

export default LoginPage;
